-- MySQL 8.0+; 105 rows: 5 roots + 25 subitems + 75 scoring categories
CREATE TABLE IF NOT EXISTS edu_evaluation_category (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
 parent_id BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '根节点为0',
 category_code VARCHAR(30) NOT NULL COMMENT '稳定分类代码',
 category_name VARCHAR(100) NOT NULL,
 category_level TINYINT NOT NULL COMMENT '1五育/2子项/3加分类',
 score TINYINT NOT NULL DEFAULT 0 COMMENT '仅三级加1分',
 description VARCHAR(500) DEFAULT NULL,
 sort_order INT NOT NULL DEFAULT 0,
 status TINYINT NOT NULL DEFAULT 1 COMMENT '1启用0停用',
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 PRIMARY KEY(id), UNIQUE KEY uk_category_code(category_code),
 KEY idx_parent(parent_id), KEY idx_level_status(category_level,status,sort_order),
 CONSTRAINT chk_category_level CHECK(category_level IN (1,2,3)),
 CONSTRAINT chk_category_score CHECK((category_level IN (1,2) AND score=0) OR (category_level=3 AND score=1)),
 CONSTRAINT chk_category_status CHECK(status IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='五育评价分类（三级树）';

-- Use category_code to resolve auto-generated IDs; the script is safe to re-run for the same codes.
START TRANSACTION;
COMMIT;

